-- Derived index-only structure, no row data. STAGING ONLY.
BEGIN;
CREATE INDEX idx_children_parent_id ON public.children USING btree (parent_id);
CREATE INDEX idx_daily_pulse_reports_child_created ON public.daily_pulse_reports USING btree (child_id, created_at);
