CREATE INDEX idx_operational_exceptions_recurrence_group ON public.operational_exceptions USING btree (recurrence_group_key) WHERE (recurrence_group_key IS NOT NULL);
CREATE INDEX idx_operational_exceptions_status ON public.operational_exceptions USING btree (status);
CREATE INDEX idx_payment_refunds_payment_id ON public.payment_refunds USING btree (payment_id);
CREATE UNIQUE INDEX idx_readiness_overrides_active_unique ON public.readiness_blocker_overrides USING btree (blocker_key) WHERE (active = true);
CREATE INDEX idx_readiness_overrides_key ON public.readiness_blocker_overrides USING btree (blocker_key);
CREATE INDEX idx_recommendations_child_created ON public.recommendations USING btree (child_id, created_at);
CREATE INDEX idx_subscriptions_child_status ON public.subscriptions USING btree (child_id, status);
CREATE UNIQUE INDEX idx_support_cases_contact_request_unique ON public.support_cases USING btree (contact_request_id) WHERE (contact_request_id IS NOT NULL);
CREATE INDEX idx_support_cases_status ON public.support_cases USING btree (status);
CREATE UNIQUE INDEX idx_teachers_application_unique ON public.teachers USING btree (application_id) WHERE (application_id IS NOT NULL);
CREATE INDEX idx_webhook_events_received_at ON public.webhook_events USING btree (received_at DESC);
CREATE INDEX idx_weekly_goals_child_week ON public.weekly_goals USING btree (child_id, week_start);
