CREATE UNIQUE INDEX uq_daily_tasks_session_child_source ON public.daily_tasks USING btree (session_id, child_id, source_key);
CREATE UNIQUE INDEX uq_manual_dev_one_paid_per_subscription ON public.payments USING btree (subscription_id) WHERE ((provider = 'manual-dev'::text) AND (status = 'paid'::text));
CREATE UNIQUE INDEX uq_paylink_one_pending_per_subscription ON public.payments USING btree (subscription_id) WHERE ((provider = 'paylink'::text) AND (status = 'pending'::text));
